package bytesconv

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestStringToBytes(t *testing.T) {
	for _, test := range []struct {
		Input  string
		Output []byte
	}{
		{"", []byte{}},
		{"a", []byte{'a'}},
		{"ab", []byte{'a', 'b'}},
		{"abc", []byte{'a', 'b', 'c'}},
		{"abcdef", []byte{'a', 'b', 'c', 'd', 'e', 'f'}},
		{"abcdefg", []byte{'a', 'b', 'c', 'd', 'e', 'f', 'g'}},
		{"abcdefg1234567890", []byte{'a', 'b', 'c', 'd', 'e', 'f', 'g', '1', '2', '3', '4', '5', '6', '7', '8', '9', '0'}},
	} {
		t.Run(test.Input, func(t *testing.T) {
			assert.Equal(t, test.Output, StringToBytes(test.Input))
		})
	}
}

func TestBytesToString(t *testing.T) {
	for _, test := range []struct {
		Input  []byte
		Output string
	}{
		{[]byte{}, ""},
		{[]byte{'a'}, "a"},
		{[]byte{'a', 'b'}, "ab"},
		{[]byte{'a', 'b', 'c'}, "abc"},
		{[]byte{'a', 'b', 'c', 'd', 'e', 'f'}, "abcdef"},
		{[]byte{'a', 'b', 'c', 'd', 'e', 'f', 'g'}, "abcdefg"},
		{[]byte{'a', 'b', 'c', 'd', 'e', 'f', 'g', '1', '2', '3', '4', '5', '6', '7', '8', '9', '0'}, "abcdefg1234567890"},
	} {
		t.Run(test.Input, func(t *testing.T) {
			assert.Equal(t, test.Output, BytesToString(test.Input))
		})
	}
}

